const CART = { items: [{ price_cents: 1250, quantity: 1 }] };

fetch("/api/status")
  .then(response => response.json())
  .then(status => { document.querySelector("#status").textContent = `Checkout ${status.version}`; });

document.querySelector("#pay").addEventListener("click", () => {
  const result = document.querySelector("#result");
  result.textContent = "Processing payment...";
  fetch("/api/checkout", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ cart: CART, method: "card" })
  })
    .then(response => response.json().then(body => ({ ok: response.ok, body })))
    .then(({ ok, body }) => {
      result.textContent = ok
        ? `Payment ${body.status}: ${(body.amount_cents / 100).toFixed(2)} via ${body.method}`
        : `Payment failed: ${body.error}`;
    })
    .catch(() => { result.textContent = "Payment failed: network error"; });
});

"""Current checkout behavior."""


def create_checkout(cart, method="card"):
    items = cart.get("items", [])
    if not items or any(item.get("quantity", 0) < 1 for item in items):
        raise ValueError("The cart needs items with positive quantities")
    if method not in ("card", "bank_transfer"):
        raise ValueError("Unsupported payment method")
    cents = sum(item["price_cents"] * item["quantity"] for item in items)
    return {"status": "pending_payment", "amount_cents": cents, "method": method}


def payment_button(checkout):
    """Return the payment button descriptor for an existing checkout flow."""
    if checkout.get("status") != "pending_payment":
        raise ValueError("Checkout is not awaiting payment")
    return {
        "label": "Pay now",
        "action": "pay",
        "amount_cents": checkout["amount_cents"],
        "method": checkout["method"],
    }

